select case when amount >= 4000 then 'high' when amount >= 900 then 'mid' else 'low' end as amount_bucket, merchant, sum(case when txn_type = 'REFUND' then 1 else 0 end) as refund_count, max(amount) - min(amount) as amount_range, count(amount) as amount_count from transactions group by case when amount >= 4000 then 'high' when amount >= 900 then 'mid' else 'low' end, merchant order by amount_count desc;
